{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Rates — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f7fbf9;--card:#ffffff;--muted:#6b7c7a;--accent:#2d7a66;--accent-2:#66a89a}
    *{box-sizing:border-box}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;line-height:1.45;margin:0;background:var(--bg);color:#02302b}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 24px;background:linear-gradient(135deg,rgba(45,122,102,.06),transparent)}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:8px;background:linear-gradient(180deg,var(--accent),var(--accent-2));display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none;font-size:14px}
    .cta{background:var(--accent);color:white;padding:8px 12px;border-radius:8px;text-decoration:none}
    main{max-width:1000px;margin:28px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr;gap:12px;padding:28px;border-radius:12px;background:linear-gradient(180deg,#fff,rgba(255,255,255,.6));box-shadow:0 6px 20px rgba(2,48,43,.05)}
    .hero h1{margin:0;font-size:26px}
    .hero p{margin:6px 0;color:var(--muted)}

    .plans{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:18px}
    .plan{background:var(--card);padding:18px;border-radius:12px;border:1px solid rgba(2,48,43,.04)}
    .plan h3{margin:0 0 6px 0}
    .price{font-size:20px;color:var(--accent);margin-bottom:10px}
    .features{color:var(--muted);font-size:14px;margin-bottom:12px}
    .join{display:inline-block;padding:8px 10px;border-radius:8px;background:transparent;border:1px solid var(--accent);color:var(--accent);text-decoration:none}

    /* Challenge */
    .challenge{margin-top:24px;padding:18px;background:linear-gradient(90deg,rgba(102,168,154,.06),transparent);border-radius:12px}
    .challenge-controls{display:flex;gap:10px;flex-wrap:wrap;align-items:center}
    select,input[type=checkbox]{padding:8px;border-radius:8px;border:1px solid #dfeeea}
    button{cursor:pointer}
    .checklist{margin-top:12px;background:#fff;padding:14px;border-radius:10px;border:1px dashed rgba(2,48,43,.06)}
    .day{display:flex;align-items:center;gap:12px;padding:6px 0;border-bottom:1px solid rgba(2,48,43,.03)}
    .day:last-child{border-bottom:0}
    .day strong{width:84px}

    /* Modal */
    .overlay{position:fixed;inset:0;background:rgba(0,0,0,.35);display:none;align-items:center;justify-content:center}
    .modal{background:white;padding:18px;border-radius:12px;width:92%;max-width:540px;box-shadow:0 12px 36px rgba(2,48,43,.18)}
    .modal h4{margin:0 0 8px 0}
    .exercise-area{min-height:120px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px}
    .circle{width:120px;height:120px;border-radius:60px;background:radial-gradient(circle at 30% 30%,var(--accent-2),var(--accent));display:flex;align-items:center;justify-content:center;color:white;font-weight:700;transition:transform 1s}
    .controls{display:flex;gap:8px}

    footer{padding:20px;text-align:center;color:var(--muted);font-size:13px;margin-top:22px}

    @media (max-width:900px){.plans{grid-template-columns:1fr}}

    @media print{body *:not(.print-section){display:none} .print-section{display:block} .checklist{border:none}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">WC</div>
      <div>
        <div style="font-weight:600">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Philosophy</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Join</a>
      <a href="pricing.html">Rates</a>
      <a href="testimonials.html">Stories</a>
      <a class="cta" href="book.html">Reserve</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div>
        <h1>Flexible membership levels built around repeatable habits</h1>
        <p>Choose a cadence that makes sense for the life you live. Memberships are framed as steady scaffolding for daily practices, not a one-time fix.</p>
      </div>
    </section>

    <section class="plans" aria-label="pricing plans">
      <div class="plan">
        <h3>Anchor — Core</h3>
        <div class="price">$19 / month</div>
        <div class="features">Weekly check-ins · Habit templates · Member library</div>
        <a class="join" href="{{PRIMARY_CTA_URL}}">Begin with Anchor</a>
      </div>
      <div class="plan" style="border:2px solid rgba(102,168,154,.12)">
        <h3>Compass — Guided</h3>
        <div class="price">$49 / month</div>
        <div class="features">Everything in Core · Monthly workshop · Goal review</div>
        <a class="join" href="{{PRIMARY_CTA_URL}}">Choose Compass</a>
      </div>
      <div class="plan">
        <h3>Haven — Full Support</h3>
        <div class="price">$99 / month</div>
        <div class="features">Personal plan · Priority booking · Small-group check-ins</div>
        <a class="join" href="{{PRIMARY_CTA_URL}}">Enter the Haven</a>
      </div>
    </section>

    <section class="challenge" aria-labelledby="challenge-label">
      <h3 id="challenge-label">7‑Day Habit Challenge — make one practice reliably yours</h3>
      <p style="color:var(--muted)">Pick a theme, generate a simple 7-day plan, then print a checklist you can stick on the fridge.</p>
      <div class="challenge-controls">
        <label>
          Theme
          <select id="theme">
            <option value="movement">Gentle movement</option>
            <option value="breath">Micro-breathing</option>
            <option value="morning">Morning reset</option>
            <option value="evening">Evening wind-down</option>
            <option value="journaling">Micro-journaling</option>
          </select>
        </label>
        <label>
          Daily target
          <select id="target">
            <option value="1">1 minute</option>
            <option value="3">3 minutes</option>
            <option value="5">5 minutes</option>
            <option value="10">10 minutes</option>
          </select>
        </label>
        <button id="generate">Create my 7‑day plan</button>
        <button id="printBtn" style="margin-left:8px;">Print checklist</button>
      </div>

      <div id="checklist" class="checklist" aria-live="polite" style="margin-top:12px">
        <div style="color:var(--muted);font-size:13px">Your checklist will appear here after generating.</div>
      </div>

      <div class="print-section" style="display:none"></div>
    </section>

    <section style="margin-top:18px;display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap">
      <div>
        <h4 style="margin:0">Try a guided exercise</h4>
        <p style="margin:6px 0;color:var(--muted)">A short, interactive moment to test a breathing or micro-journaling practice.</p>
      </div>
      <div style="display:flex;gap:8px">
        <button id="tryBtn" class="join">Try it now</button>
        <a class="join" href="book.html" style="background:var(--accent);color:#fff">Book a session</a>
      </div>
    </section>
  </main>

  <div id="overlay" class="overlay" role="dialog" aria-modal="true">
    <div class="modal" role="document">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">
        <h4>Guided micro-practice</h4>
        <button id="closeModal" aria-label="Close">✕</button>
      </div>

      <div style="display:flex;gap:8px;margin-bottom:8px;flex-wrap:wrap">
        <button data-ex="breath">Breathing</button>
        <button data-ex="journal">Journaling</button>
        <button data-ex="intention">Intention</button>
      </div>

      <div class="exercise-area">
        <div id="breathArea" style="display:none;flex-direction:column;align-items:center">
          <div class="circle" id="breathCircle">3</div>
          <div style="color:var(--muted);font-size:13px">Follow the expanding circle. 3 rounds.</div>
        </div>

        <div id="journalArea" style="display:none;flex-direction:column;align-items:center">
          <textarea id="journalInput" placeholder="Write one sentence about how today felt..." style="width:100%;min-height:80px;padding:10px;border-radius:8px;border:1px solid #e6f0ec"></textarea>
          <div style="color:var(--muted);font-size:13px">Time: 3 minutes (set a gentle timer)</div>
        </div>

        <div id="intentionArea" style="display:none;flex-direction:column;align-items:center">
          <div style="font-size:16px;font-weight:600">Set a single intention</div>
          <input id="intentInput" placeholder="I intend to..." style="padding:8px;width:100%;border-radius:8px;border:1px solid #e6f0ec" />
        </div>

      </div>

      <div class="controls" style="margin-top:12px">
        <button id="startBtn" class="join">Start</button>
        <button id="stopBtn" style="display:none">Stop</button>
        <button id="saveBtn" style="display:none">Save note</button>
      </div>
    </div>
  </div>

  <footer>
    <div>{{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    <div style="margin-top:6px;color:var(--muted)">Membership access and scheduling available. No medical advice provided.</div>
  </footer>

  <script>
    // Habit challenge generator
    (function(){
      const themes = {
        movement:["1 minute gentle stretch","2 knee lifts","1 minute shoulder rolls","1 minute neck release","short walk or step-in-place","light hip circles","deep breaths & gentle reach"],
        breath:["Box breathing (4-4-4-4)","Long exhale focus (3x)","4-count inhale,6-count exhale","Alternate nostril (2 min)","3 full belly breaths","Paced 5-5 breathing","3 rounds of 6-6 breathing"],
        morning:["Sip water + 1 min stretch","Set one small intention","5 breaths before phone","Open curtains + deep breath","Gentle movement for 3 min","Write one gratitude","Check posture & breathe"],
        evening:["2 minute body scan","Journal one highlight","Slow breathing for 3 min","Turn off screens 30 min early","Warm drink & stretch","Reflect on wins","Prepare tomorrow with one task"],
        journaling:["One-sentence reflection","Describe a win","Note a challenge + small next step","List 3 sensory details","Write a quick gratitude","What felt ok today?","Set a focus for tomorrow"]
      };

      const themeSel = document.getElementById('theme');
      const targetSel = document.getElementById('target');
      const genBtn = document.getElementById('generate');
      const checklist = document.getElementById('checklist');
      const printBtn = document.getElementById('printBtn');
      const printSection = document.querySelector('.print-section');

      function buildList(themeKey,target){
        const items = themes[themeKey] || [];
        const frag = document.createElement('div');
        frag.innerHTML = '<div style="font-weight:600;margin-bottom:6px">7‑day checklist — '+(themeSel.options[themeSel.selectedIndex].text)+', '+target+' daily</div>';
        items.slice(0,7).forEach((t,i)=>{
          const d = document.createElement('div'); d.className='day';
          d.innerHTML = '<strong>Day '+(i+1)+'</strong><label style="flex:1"><input type="checkbox"> '+t+' <span style="color:var(--muted);font-size:13px;display:block">Repeat for '+target+' each day</span></label>';
          frag.appendChild(d);
        });
        frag.appendChild(document.createElement('div'));
        return frag.innerHTML;
      }

      genBtn.addEventListener('click',function(){
        const theme = themeSel.value;
        const target = targetSel.value;
        checklist.innerHTML = buildList(theme,target);
        printSection.innerHTML = checklist.innerHTML;
        printSection.style.display = 'none';
      });

      printBtn.addEventListener('click',function(){
        // prepare a printable version
        printSection.innerHTML = checklist.innerHTML;
        document.querySelectorAll('body *').forEach(el=>el.classList.add('print-hide'));
        printSection.classList.add('print-section');
        printSection.style.display = 'block';
        window.print();
        printSection.style.display = 'none';
      });
    })();

    // Guided modal logic
    (function(){
      const overlay = document.getElementById('overlay');
      const tryBtn = document.getElementById('tryBtn');
      const closeModal = document.getElementById('closeModal');
      const startBtn = document.getElementById('startBtn');
      const stopBtn = document.getElementById('stopBtn');
      const saveBtn = document.getElementById('saveBtn');
      const breathArea = document.getElementById('breathArea');
      const journalArea = document.getElementById('journalArea');
      const intentArea = document.getElementById('intentionArea');
      const circle = document.getElementById('breathCircle');
      let mode = 'breath';
      let breathTimer=null, step=0, rounds=3;

      function showMode(m){
        mode=m;
        breathArea.style.display = m==='breath'? 'flex':'none';
        journalArea.style.display = m==='journal'? 'flex':'none';
        intentArea.style.display = m==='intention'? 'flex':'none';
        saveBtn.style.display = m==='journal'?'inline-block':'none';
      }

      document.querySelectorAll('[data-ex]').forEach(btn=>{
        btn.addEventListener('click',()=> showMode(btn.getAttribute('data-ex')));
      });

      tryBtn.addEventListener('click',()=>{
        overlay.style.display='flex';
        showMode('breath');
      });
      closeModal.addEventListener('click',()=>{ overlay.style.display='none'; stop(); });

      function breatheStep(){
        step = (step%3)+1;
        if(step===1){ circle.style.transform='scale(1.15)'; circle.textContent='In'; }
        if(step===2){ circle.style.transform='scale(.85)'; circle.textContent='Hold'; }
        if(step===3){ circle.style.transform='scale(1)'; circle.textContent='Out'; }
      }

      function start(){
        if(mode==='breath'){
          step=0; breatheStep(); breathTimer=setInterval(breatheStep,2000);
          startBtn.style.display='none'; stopBtn.style.display='inline-block';
        } else if(mode==='journal'){
          startBtn.style.display='none'; stopBtn.style.display='inline-block';
          // simple countdown 3 minutes
          let t=180;
          journalArea.querySelector('div') && (journalArea.querySelector('div').textContent='Time left: 3:00');
          breathTimer = setInterval(()=>{
            t--; const m=Math.floor(t/60); const s=t%60; journalArea.querySelector('div').textContent='Time left: '+m+':'+(s<10?'0'+s:s);
            if(t<=0) stop();
          },1000);
        } else if(mode==='intention'){
          // small flash and then close
          intentArea.querySelector('input').style.background='#f1fff8';
          setTimeout(()=>{ intentArea.querySelector('input').style.background=''; overlay.style.display='none'; },1200);
        }
      }
      function stop(){
        if(breathTimer) clearInterval(breathTimer); breathTimer=null; startBtn.style.display='inline-block'; stopBtn.style.display='none';
      }
      startBtn.addEventListener('click',()=>{ start(); });
      stopBtn.addEventListener('click',()=>{ stop(); });
      saveBtn.addEventListener('click',()=>{
        const note = document.getElementById('journalInput').value;
        if(note.trim()){
          alert('Saved note to your local device: \n'+note.slice(0,200));
          document.getElementById('journalInput').value='';
          overlay.style.display='none';
        } else alert('Write a quick sentence before saving.');
      });

      // close on Escape
      window.addEventListener('keydown',e=>{ if(e.key==='Escape') overlay.style.display='none'; });
    })();
  </script>
</body>
</html>"} 
{"path":"testimonials.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Stories — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfdfc;--muted:#5f6f6d;--accent:#2d7a66}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;margin:0;color:#03302b;background:var(--bg)}
    header{display:flex;justify-content:space-between;padding:16px 20px;background:linear-gradient(180deg,rgba(45,122,102,.05),transparent)}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    .wrap{max-width:980px;margin:24px auto;padding:0 18px}
    .lead{background:white;padding:18px;border-radius:12px;border:1px solid rgba(2,48,43,.04);display:flex;align-items:center;gap:14px}
    .lead .badge{width:44px;height:44px;border-radius:10px;background:linear-gradient(90deg,#66a89a,#2d7a66);display:flex;align-items:center;justify-content:center;color:white;font-weight:700}

    .grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:18px}
    .card{background:white;padding:14px;border-radius:10px;border:1px solid rgba(2,48,43,.04)}
    .quote{font-style:italic;color:#0b3b33}
    .meta{color:var(--muted);font-size:13px;margin-top:8px}

    .mini-try{display:flex;gap:8px;align-items:center;margin-top:12px}
    .mini-try button{padding:8px;border-radius:8px;border:1px solid rgba(2,48,43,.06);background:#fff}

    @media (max-width:800px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div style="width:44px;height:44px;border-radius:10px;background:linear-gradient(90deg,#66a89a,#2d7a66);display:flex;align-items:center;justify-content:center;color:white">WC</div>
      <div style="font-weight:600">{{BUSINESS_NAME}}</div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Philosophy</a>
      <a href="programs.html">Offerings</a>
      <a href="pricing.html">Rates</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <div class="wrap">
    <section class="lead">
      <div class="badge">S</div>
      <div>
        <div style="font-weight:700">Stories from members</div>
        <div style="color:var(--muted);font-size:14px">Short accounts of how small, steady practices shaped routines over weeks.</div>
      </div>
      <div style="margin-left:auto;text-align:right">
        <div style="font-size:12px;color:var(--muted)">Want to try a micro-practice?</div>
        <div class="mini-try"><button id="trySmall">Try it now</button><a href="book.html" style="padding:8px;border-radius:8px;text-decoration:none;background:#2d7a66;color:#fff">Reserve time</a></div>
      </div>
    </section>

    <section class="grid" aria-live="polite">
      <article class="card">
        <div class="quote">"I used to aim for big mornings. Instead, I built a 3-minute habit and that was the thing that stuck."</div>
        <div class="meta">— S., local teacher • 6 months in</div>
      </article>
      <article class="card">
        <div class="quote">"Weekly frameworks helped me plan my days without friction. Small wins added up into real steadiness."</div>
        <div class="meta">— R., designer</div>
      </article>
      <article class="card">
        <div class="quote">"The group sessions taught me a simple scaffold: notice, act, review. I track it in a checklist now."</div>
        <div class="meta">— L., nurse</div>
      </article>
      <article class="card">
        <div class="quote">"A short breathing exercise before tough calls changed how I responded. It took no time but made a difference."</div>
        <div class="meta">— J., manager</div>
      </article>
    </section>

    <section style="margin-top:18px">
      <h3 style="margin-bottom:6px">Share your experience</h3>
      <p style="color:var(--muted);margin-top:0">If one of these stories resonates, book a short conversation or reply to our email — we'd love to document your pathway to steadier routines.</p>
      <a href="mailto:{{EMAIL}}" style="display:inline-block;margin-top:8px;padding:8px 12px;border-radius:8px;background:var(--accent);color:#fff;text-decoration:none">Write to us</a>
    </section>
  </div>

  <div id="overlaySmall" style="position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(0,0,0,.3)">
    <div style="background:#fff;padding:18px;border-radius:10px;width:90%;max-width:460px">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <strong>Micro-breath practice</strong>
        <button id="closeSmall">✕</button>
      </div>
      <div style="margin-top:12px;display:flex;flex-direction:column;gap:8px">
        <div style="font-size:14px;color:#0b3b33">Follow a 90 second cycle: breathe in for 4, out for 6. Repeat 3 times.</div>
        <div style="display:flex;gap:8px;justify-content:flex-end">
          <button id="startSmall" style="padding:8px;border-radius:8px">Start</button>
        </div>
      </div>
    </div>
  </div>

  <script>
    // Small modal reuse of guided exercise, simplified
    const overlaySmall = document.getElementById('overlaySmall');
    document.getElementById('trySmall').addEventListener('click',()=> overlaySmall.style.display='flex');
    document.getElementById('closeSmall').addEventListener('click',()=> overlaySmall.style.display='none');
    document.getElementById('startSmall').addEventListener('click',()=>{
      let rounds=3; let r=0; const step = ()=>{
        if(r>=rounds){ alert('Done. Notice the change.'); overlaySmall.style.display='none'; return; }
        r++; setTimeout(step,1500);
      }; step();
    });
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f6fbfa;--accent:#2d7a66;--muted:#5d6f6b}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;margin:0;background:var(--bg);color:#022f2a}
    header{display:flex;justify-content:space-between;padding:14px 20px;background:linear-gradient(180deg,rgba(45,122,102,.04),transparent)}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    .container{max-width:920px;margin:24px auto;padding:0 20px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:18px}
    .panel{background:white;padding:16px;border-radius:12px;border:1px solid rgba(2,48,43,.04)}

    label{display:block;margin:8px 0 4px;font-size:14px}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #eaf5f1}
    .actions{display:flex;gap:8px;align-items:center;margin-top:12px}
    .primary{background:var(--accent);color:white;padding:10px 12px;border-radius:8px;text-decoration:none;border:none}

    .habit-tool{background:linear-gradient(90deg,rgba(102,168,154,.06),transparent);padding:12px;border-radius:10px}

    @media (max-width:860px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div style="width:44px;height:44px;border-radius:8px;background:linear-gradient(90deg,#66a89a,#2d7a66);display:flex;align-items:center;justify-content:center;color:white;font-weight:700">WC</div>
      <div style="font-weight:700">Reserve time</div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="pricing.html">Rates</a>
      <a href="testimonials.html">Stories</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main class="container">
    <div class="grid">
      <div>
        <section class="panel">
          <h2 style="margin-top:0">Book a conversation</h2>
          <p style="color:var(--muted)">Choose a slot or request a private intake. Sessions focus on habits, frameworks, and measurable steps.</p>

          <form id="bookingForm" onsubmit="return false;">
            <label for="name">Your name</label>
            <input id="name" required placeholder="Full name" />
            <label for="email">Email</label>
            <input id="email" type="email" required placeholder="you@domain.com" />
            <label for="type">Session type</label>
            <select id="type">
              <option>Intro: 20 minutes</option>
              <option>Deep session: 50 minutes</option>
              <option>Planning review: 30 minutes</option>
            </select>
            <label for="note">A short note</label>
            <textarea id="note" placeholder="What would you like to focus on?" rows="4"></textarea>

            <div class="actions">
              <button class="primary" id="bookNow">Request time</button>
              <button id="mailto" style="padding:10px;border-radius:8px">Email a request</button>
            </div>
          </form>

          <p style="margin-top:12px;color:var(--muted);font-size:13px">After requesting we will follow up to confirm details and suggest starting habits you can trial in the interim.</p>
        </section>

        <section class="panel" style="margin-top:12px">
          <h3 style="margin-top:0">Quick try-before-you-book</h3>
          <p style="color:var(--muted);margin-bottom:8px">A short guided moment to sample the approach.</p>
          <div style="display:flex;gap:8px">
            <button id="tryBooking" style="padding:10px;border-radius:8px;border:1px solid rgba(2,48,43,.06);background:#fff">Try it now</button>
            <a href="pricing.html" style="padding:10px;border-radius:8px;background:var(--accent);color:#fff;text-decoration:none">See rates</a>
          </div>
        </section>
      </div>

      <aside>
        <div class="panel habit-tool">
          <h4 style="margin-top:0">On-the-spot 7-day starter</h4>
          <p style="color:var(--muted);font-size:13px;margin-top:0">Generate a compact weekly checklist you can use right away.</p>
          <div style="display:flex;gap:8px;margin-top:8px">
            <select id="hbTheme">
              <option value="movement">Movement</option>
              <option value="breath">Breath</option>
              <option value="journaling">Journaling</option>
            </select>
            <button id="hbGen">Generate</button>
          </div>
          <div id="hbOut" style="margin-top:8px;color:var(--muted);font-size:14px">No plan yet.</div>
          <button id="hbPrint" style="margin-top:8px;padding:8px;border-radius:8px">Print checklist</button>
        </div>

        <div class="panel" style="margin-top:12px">
          <h4 style="margin-top:0">Need help?</h4>
          <p style="color:var(--muted);font-size:13px;margin-top:0">Call or email to arrange a time that fits your week.</p>
          <div style="font-weight:600;margin-top:6px">{{PHONE}}</div>
          <a href="mailto:{{EMAIL}}" style="display:inline-block;margin-top:6px;background:var(--accent);color:#fff;padding:8px;border-radius:8px;text-decoration:none">Contact</a>
        </div>
      </aside>
    </div>
  </main>

  <div id="miniModal" style="position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(0,0,0,.25)">
    <div style="background:#fff;padding:16px;border-radius:10px;width:90%;max-width:520px">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <strong>Guided micro-practice</strong>
        <button id="miniClose">✕</button>
      </div>
      <div style="margin-top:12px" id="miniContent">
        <p style="margin:0 0 8px 0;color:var(--muted)">Choose one: breathing (2 min) or a micro-journal prompt (write a sentence).</p>
        <div style="display:flex;gap:8px;justify-content:flex-end">
          <button id="miniBreath" style="padding:8px;border-radius:8px">Breath</button>
          <button id="miniJournal" style="padding:8px;border-radius:8px">Journal</button>
        </div>
      </div>
    </div>
  </div>

  <script>
    // Booking UI (client-side only)
    document.getElementById('bookNow').addEventListener('click',function(){
      const name = document.getElementById('name').value.trim();
      const email = document.getElementById('email').value.trim();
      if(!name || !email) return alert('Please enter name and email.');
      alert('Thanks, '+name+". We've received your request and will follow up at " + email + '.');
      // Simulated success
      document.getElementById('bookingForm').reset();
    });

    document.getElementById('mailto').addEventListener('click',function(){
      const subject = encodeURIComponent('Requesting a session');
      const body = encodeURIComponent('Hi,\n\nI would like to request a session. Please suggest available times.\n\nThanks.');
      window.location.href = 'mailto:{{EMAIL}}?subject='+subject+'&body='+body;
    });

    // Habit builder in aside
    (function(){
      const map = {
        movement:["1 min stretch","2 min walk","ankle rolls","shoulder circles","sit-stand 5x","gentle twist","deep breath + reach"],
        breath:["4-6 breathing x3","slow exhale focus","box breathing 2 rounds","belly breaths 3x","sigh release 2x","counted breath 4x","long exhale 3x"],
        journaling:["one-sentence log","note a small win","record a worry + step","3-word summary","gratitude line","tiny plan for next day","capture a sensory detail"]
      };
      const hbGen = document.getElementById('hbGen');
      const hbOut = document.getElementById('hbOut');
      const hbPrint = document.getElementById('hbPrint');
      hbGen.addEventListener('click',()=>{
        const key = document.getElementById('hbTheme').value;
        const list = map[key] || [];
        hbOut.innerHTML = '<ol style="padding-left:18px;margin:8px 0">'+list.slice(0,7).map(i=>'<li>'+i+'</li>').join('')+'</ol>';
        hbPrint.dataset.html = hbOut.innerHTML;
      });
      hbPrint.addEventListener('click',()=>{
        const w = window.open('about:blank');
        w.document.write('<!doctype html><meta charset="utf-8"><title>Checklist</title><style>body{font-family:system-ui;padding:18px}</style><h3>7-day checklist</h3>'+ (hbPrint.dataset.html||'<p>No plan generated</p>'));
        w.print();
        w.close();
      });
    })();

    // Mini guided modal reuse
    const miniModal = document.getElementById('miniModal');
    document.getElementById('tryBooking').addEventListener('click',()=> miniModal.style.display='flex');
    document.getElementById('miniClose').addEventListener('click',()=> miniModal.style.display='none');
    document.getElementById('miniBreath').addEventListener('click',()=>{
      alert('Breathe in for 4, out for 6. Repeat 3 times. Notice changes.'); miniModal.style.display='none';
    });
    document.getElementById('miniJournal').addEventListener('click',()=>{
      const one = prompt('Write one sentence about how your day felt.');
      if(one) alert('Nice — that sentence can be a small anchor.');
      miniModal.style.display='none';
    });
  </script>
</body>
</html>"} 
